from __future__ import annotations

import hashlib
import json
import urllib.request
from datetime import datetime, timezone


class Execution:
    name: str = "fetch_orca6_dataset"
    description: str = "Retrieves the KM3NeT/ORCA6 433 kt-y public dataset (ROOT response file, binning JSON, chi-square landscapes) with checksum verification."
    category: str = "data"

    inputs: list[dict] = []

    outputs: list[dict] = [
        {"name": "orca_raw", "type": dict},
    ]

    parameters: dict = {
        "request_timeout_seconds": {"type": float, "default": 120},
    }

    DATASET_API = "https://opendata.km3net.de/api/datasets/:persistentId/?persistentId=doi:10.5072/FK2/Y0UXVW"
    FILE_API = "https://opendata.km3net.de/api/access/datafile/%d"
    DOI = "10.5072/FK2/Y0UXVW"
    DATASET_PAGE = "https://opendata.km3net.de/dataset.xhtml?persistentId=doi:10.5072/FK2/Y0UXVW"

    def _get(self, url, timeout):
        request = urllib.request.Request(url, headers={"User-Agent": "hermes-workflow-neutrino-liv/1.0"})
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.read()

    def _download(self, file_id, timeout):
        base = self.FILE_API % int(file_id)
        try:
            return self._get(base + "?format=original", timeout), base + "?format=original"
        except Exception:
            return self._get(base, timeout), base

    def _parse_chi2(self, raw):
        rows = []
        for line in raw.decode("utf-8", "replace").splitlines():
            line = line.strip()
            if not line or line.lower().startswith("theta"):
                continue
            parts = line.split(",")
            if len(parts) < 3:
                continue
            try:
                rows.append([float(parts[0]), float(parts[1]), float(parts[2])])
            except ValueError:
                continue
        return rows

    def run(self, inputs, parameters, context):
        timeout = int(parameters.get("request_timeout_seconds", 120))
        retrieved_at = datetime.now(timezone.utc).isoformat()
        errors: list[dict] = []

        try:
            manifest = json.loads(self._get(self.DATASET_API, timeout).decode("utf-8"))
        except Exception as exc:
            return {"orca_raw": {"status": "metadata_unavailable", "errors": ["%s: %s" % (type(exc).__name__, exc)], "retrieved_at": retrieved_at}}

        version = manifest["data"]["latestVersion"]
        files = []
        payloads = {}
        for item in version.get("files", []):
            info = item.get("dataFile") or {}
            name = str(info.get("filename", ""))
            if not name:
                continue
            try:
                raw, url_used = self._download(info.get("id"), timeout)
            except Exception as exc:
                errors.append({"file": name, "error": "%s: %s" % (type(exc).__name__, exc)})
                continue
            md5 = hashlib.md5(raw).hexdigest()
            declared = (info.get("checksum") or {}).get("value") or info.get("md5") or ""
            payloads[name] = raw
            files.append({
                "filename": name,
                "downloaded_bytes": len(raw),
                "declared_bytes": info.get("filesize"),
                "content_type": info.get("contentType"),
                "computed_md5": md5,
                "declared_md5": declared,
                "checksum_match": bool(declared) and declared.lower() == md5.lower(),
                "url": url_used,
            })

        bins = None
        for name, raw in payloads.items():
            if name.endswith(".json"):
                try:
                    payload = json.loads(raw.decode("utf-8", "replace"))
                    summary = {}
                    for key, values in payload.items():
                        if isinstance(values, list) and values:
                            summary[key] = {
                                "bins": max(0, len(values) - 1),
                                "min": values[0],
                                "max": values[-1],
                            }
                    bins = {"keys": list(payload.keys()), "summary": summary}
                except Exception as exc:
                    errors.append({"file": name, "error": "bins JSON parse failed: %s" % exc})

        readme = None
        for name, raw in payloads.items():
            if name.lower().startswith("readme"):
                text = raw.decode("utf-8", "replace")
                readme = {"filename": name, "chars": len(text), "excerpt": text[:1400]}

        landscapes = {}
        for name, raw in payloads.items():
            upper = name.upper()
            if not name.lower().endswith(".csv"):
                continue
            if "IO" in upper or "INVERTED" in upper:
                landscapes["IO"] = self._parse_chi2(raw)
            elif "NO" in upper or "NORMAL" in upper:
                landscapes["NO"] = self._parse_chi2(raw)

        root_file = next((f for f in files if f["filename"].lower().endswith(".root")), None)
        status = "ok" if landscapes.get("NO") and landscapes.get("IO") else "partial"

        return {"orca_raw": {
            "status": status,
            "dataset": {
                "title": "KM3NeT/ORCA6 433 kt-y neutrino oscillation open dataset (v%s)" % version.get("versionNumber"),
                "doi": self.DOI,
                "url": self.DATASET_PAGE,
                "release_time": version.get("releaseTime"),
                "metadata_api": self.DATASET_API,
            },
            "files": files,
            "root_file": root_file,
            "root_accessible": bool(root_file and root_file.get("checksum_match")),
            "root_content_note": "The ROOT file holds binned_data, binned_muon and binned_nu_response trees; the workflow runtime has no ROOT reader, so those trees are not decoded here.",
            "binning": bins,
            "readme": readme,
            "chi2_landscapes": {
                "NO": {"rows": landscapes.get("NO") or [], "n": len(landscapes.get("NO") or [])},
                "IO": {"rows": landscapes.get("IO") or [], "n": len(landscapes.get("IO") or [])},
            },
            "errors": errors,
            "retrieved_at": retrieved_at,
            "limitations": [
                "The two chi-square landscapes are the collaboration's published scan over theta23 and dm31; they are analysed here, not regenerated.",
                "Binned detector response (ROOT) is retrieved and checksum-verified but not decoded in this runtime.",
            ],
        }}

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

from __future__ import annotations

import json
import math


class Execution:
    name: str = "analyze_icecube_distribution"
    description: str = "Characterises the IceCube track sample: energy and zenith distributions, angular resolution and a documented single power-law probe."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "icecube_raw", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "icecube_analysis", "type": dict},
    ]

    parameters: dict = {
        "fit_min_log10_energy": {"type": float, "default": 5.0},
        "fit_max_log10_energy": {"type": float, "default": 6.75},
    }

    def _unwrap(self, inputs, key):
        value = inputs.get(key)
        if isinstance(value, str) and value.strip()[:1] == "{":
            try:
                value = json.loads(value)
            except Exception:
                return {}
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value if isinstance(value, dict) else {}

    def _probe(self, centers, counts, x_min, x_max):
        xs, ys, ws = [], [], []
        for x, n in zip(centers, counts):
            if n < 20 or x < x_min or x > x_max:
                continue
            xs.append(x)
            ys.append(math.log10(n))
            ws.append(float(n))
        if len(xs) < 4:
            return None
        sw = sum(ws)
        mx = sum(w * x for w, x in zip(ws, xs)) / sw
        my = sum(w * y for w, y in zip(ws, ys)) / sw
        sxx = sum(w * (x - mx) ** 2 for w, x in zip(ws, xs))
        sxy = sum(w * (x - mx) * (y - my) for w, x, y in zip(ws, xs, ys))
        if sxx <= 0:
            return None
        slope = sxy / sxx
        intercept = my - slope * mx
        chi2 = sum(w * (y - (intercept + slope * x)) ** 2 for w, x, y in zip(ws, xs, ys))
        dof = max(1, len(xs) - 2)
        slope_err = math.sqrt(max(chi2 / dof, 1.0) / sxx)
        return {"slope": slope, "slope_error": slope_err, "chi2": chi2, "dof": dof, "n_bins": len(xs), "range": [xs[0], xs[-1]]}

    def run(self, inputs, parameters, context):
        raw = self._unwrap(inputs, "icecube_raw")
        x_min = float(parameters.get("fit_min_log10_energy", 5.0))
        x_max = float(parameters.get("fit_max_log10_energy", 6.75))

        sample = raw.get("sample") or {}
        if not sample.get("energy_counts"):
            return {"icecube_analysis": {"status": "no_input", "message": "IceCube event summary is missing or empty."}}

        centers = sample["energy_bin_centers_log10_gev"]
        counts = sample["energy_counts"]
        total = int(sample.get("events") or sum(counts))

        decades = {}
        for x, n in zip(centers, counts):
            key = int(math.floor(x))
            decades[key] = decades.get(key, 0) + n

        probe = self._probe(centers, counts, x_min, x_max)
        probe_block = None
        if probe:
            adequate = (probe["chi2"] / probe["dof"]) <= 3.0
            probe_block = {
                "model": "counts per 0.25 dex fitted as log10(N) = a + b log10(E/GeV); for dN/dE ~ E^-gamma, gamma = 1 - b",
                "fit_range_log10_gev": probe["range"],
                "bins_used": probe["n_bins"],
                "slope_per_dex": round(probe["slope"], 3),
                "slope_error": round(probe["slope_error"], 3),
                "gamma": round(1.0 - probe["slope"], 3),
                "gamma_error": round(probe["slope_error"], 3),
                "chi2": round(probe["chi2"], 1),
                "dof": probe["dof"],
                "chi2_per_dof": round(probe["chi2"] / probe["dof"], 1),
                "adequate_description": adequate,
                "note": "A single power law is inadequate when chi2/dof is large; gamma then only documents that failure and no spectral conclusion is drawn.",
            }

        upgoing = float(sample.get("upgoing_fraction") or 0.0)
        n_up = upgoing * total
        n_down = total - n_up
        ratio = n_up / n_down if n_down else None
        ratio_err = ratio * math.sqrt(1.0 / max(n_up, 1.0) + 1.0 / max(n_down, 1.0)) if ratio else None

        return {"icecube_analysis": {
            "status": "ok" if raw.get("status") == "ok" else "partial_input",
            "dataset": raw.get("dataset"),
            "sample_size": total,
            "seasons": sample.get("seasons"),
            "observation_window_utc": sample.get("utc_range"),
            "energy": {
                "median_log10_gev": sample.get("median_log10_energy"),
                "p90_log10_gev": sample.get("p90_log10_energy"),
                "max_log10_gev": sample.get("max_log10_energy"),
                "max_energy_gev": round(10 ** float(sample.get("max_log10_energy") or 0), 1),
                "counts_per_decade": {str(k): v for k, v in sorted(decades.items())},
                "events_above_1pev": sample.get("events_above_1pev"),
                "events_above_10pev": sample.get("events_above_10pev"),
                "mode_decade_log10_gev": max(decades, key=decades.get) if decades else None,
            },
            "angular": {
                "median_error_deg": sample.get("median_angular_error_deg"),
                "note": "Angular error is the per-event reconstruction uncertainty published in the release.",
            },
            "zenith": {
                "convention": "IceCube local zenith; this release satisfies Dec = zenith - 90 deg, so zenith > 90 deg is up-going (Earth-crossing, northern sky).",
                "upgoing_fraction": upgoing,
                "upgoing_events": int(round(n_up)),
                "downgoing_events": int(round(n_down)),
                "up_down_ratio": round(ratio, 4) if ratio else None,
                "up_down_ratio_error": round(ratio_err, 4) if ratio_err else None,
                "note": "The horizon ratio is not expected to be unity: effective area, trigger conditions and Earth attenuation break the symmetry.",
            },
            "power_law_probe": probe_block,
            "highest_energy_events": sample.get("highest_energy_events"),
            "histograms": {
                "energy": {"centers_log10_gev": centers, "counts": counts},
                "zenith": {"centers_deg": sample.get("zenith_bin_centers_deg"), "counts": sample.get("zenith_counts")},
            },
            "files": raw.get("files"),
            "retrieval_errors": raw.get("errors") or [],
            "retrieved_at": raw.get("retrieved_at"),
            "liv_fit_performed": False,
            "liv_note": "No LIV coefficient is fitted or constrained at this stage.",
            "limitations": list(raw.get("limitations") or []) + [
                "Counts mix atmospheric and astrophysical neutrinos; no purity separation or unfolding is applied.",
                "Reconstructed muon energy is not the neutrino energy; interpreting the shape requires the detector response.",
            ],
        }}

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

from __future__ import annotations

import json
import math


class Execution:
    name: str = "analyze_orca_oscillations"
    description: str = "Profiles the ORCA6 chi-square landscapes to extract best-fit theta23 and dm31, their intervals and the mass-ordering preference."
    category: str = "processing"

    inputs: list[dict] = [
        {"name": "orca_raw", "type": dict},
    ]

    outputs: list[dict] = [
        {"name": "orca_analysis", "type": dict},
    ]

    parameters: dict = {
        "one_sigma_dchi2": {"type": float, "default": 1.0},
        "ninety_percent_dchi2": {"type": float, "default": 2.71},
    }

    def _unwrap(self, inputs, key):
        value = inputs.get(key)
        if isinstance(value, str) and value.strip()[:1] == "{":
            try:
                value = json.loads(value)
            except Exception:
                return {}
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value if isinstance(value, dict) else {}

    def _profile(self, rows, index):
        profile = {}
        for row in rows:
            key = row[index]
            if key not in profile or row[2] < profile[key]:
                profile[key] = row[2]
        return profile

    def _interval(self, profile, best_key, base, threshold):
        keys = sorted(profile)
        try:
            start = keys.index(best_key)
        except ValueError:
            return None
        low = keys[start]
        index = start
        while index - 1 >= 0 and (profile[keys[index - 1]] - base) <= threshold:
            index -= 1
            low = keys[index]
        if index > 0:
            x1, y1 = keys[index - 1], profile[keys[index - 1]] - base
            x2, y2 = keys[index], profile[keys[index]] - base
            if y1 != y2:
                low = x1 + (threshold - y1) * (x2 - x1) / (y2 - y1)
        high = keys[start]
        index = start
        while index + 1 < len(keys) and (profile[keys[index + 1]] - base) <= threshold:
            index += 1
            high = keys[index]
        if index < len(keys) - 1:
            x1, y1 = keys[index], profile[keys[index]] - base
            x2, y2 = keys[index + 1], profile[keys[index + 1]] - base
            if y1 != y2:
                high = x1 + (threshold - y1) * (x2 - x1) / (y2 - y1)
        return [round(low, 4), round(high, 4)]

    def _ordering_block(self, rows, sigma1, sigma90):
        if not rows:
            return None
        best = min(rows, key=lambda row: row[2])
        base = best[2]
        theta_profile = self._profile(rows, 0)
        dm_profile = self._profile(rows, 1)
        theta_counts = {}
        for row in rows:
            theta_counts[row[0]] = theta_counts.get(row[0], 0) + 1
        modal_theta = max(theta_counts.values()) if theta_counts else 0
        sparse = [row for row in rows if theta_counts.get(row[0], 0) < 0.8 * modal_theta]
        return {
            "best_fit": {
                "theta23_deg": round(best[0], 4),
                "sin2_theta23": round(math.sin(math.radians(best[0])) ** 2, 4),
                "dm31_ev2": best[1],
                "abs_dm31_ev2": abs(best[1]),
                "chi2": round(best[2], 3),
            },
            "theta23_1sigma": self._interval(theta_profile, best[0], base, sigma1),
            "theta23_90pct": self._interval(theta_profile, best[0], base, sigma90),
            "dm31_1sigma": self._interval(dm_profile, best[1], base, sigma1),
            "dm31_90pct": self._interval(dm_profile, best[1], base, sigma90),
            "theta23_profile": [{"theta23_deg": key, "delta_chi2": round(value - base, 3)} for key, value in sorted(theta_profile.items())],
            "dm31_profile": [{"dm31_ev2": key, "delta_chi2": round(value - base, 3)} for key, value in sorted(dm_profile.items())],
            "rows_used": len(rows),
            "theta23_values": len(theta_profile),
            "dm31_values": len(dm_profile),
            "refinement_rows_included": len(sparse),
        }

    def run(self, inputs, parameters, context):
        raw = self._unwrap(inputs, "orca_raw")
        sigma1 = float(parameters.get("one_sigma_dchi2", 1.0))
        sigma90 = float(parameters.get("ninety_percent_dchi2", 2.71))

        landscapes = raw.get("chi2_landscapes") or {}
        no_rows = (landscapes.get("NO") or {}).get("rows") or []
        io_rows = (landscapes.get("IO") or {}).get("rows") or []
        if not no_rows or not io_rows:
            return {"orca_analysis": {"status": "no_input", "message": "One or both chi-square landscapes are missing."}}

        no_block = self._ordering_block(no_rows, sigma1, sigma90)
        io_block = self._ordering_block(io_rows, sigma1, sigma90)

        delta = io_block["best_fit"]["chi2"] - no_block["best_fit"]["chi2"]
        significance = math.sqrt(abs(delta))
        preferred = "NO" if delta > 0 else "IO"

        return {"orca_analysis": {
            "status": "ok" if raw.get("status") == "ok" else "partial_input",
            "dataset": raw.get("dataset"),
            "binning": raw.get("binning"),
            "files": raw.get("files"),
            "checksums_all_match": all(bool(f.get("checksum_match")) for f in (raw.get("files") or [])),
            "root_accessible": raw.get("root_accessible"),
            "root_content_note": raw.get("root_content_note"),
            "readme_excerpt": (raw.get("readme") or {}).get("excerpt"),
            "mass_ordering": {
                "normal": no_block,
                "inverted": io_block,
                "delta_chi2_no_minus_io": round(-delta, 3),
                "delta_chi2_definition": "chi2_min(IO) - chi2_min(NO); collective rows are included in each minimum",
                "preferred_ordering": preferred,
                "significance_sigma_1dof": round(significance, 3),
                "note": "sqrt(|delta chi2|) is an approximate one-degree-of-freedom significance for the ordering comparison.",
            },
            "theta23_deg_consistency": {
                "normal": no_block["best_fit"]["theta23_deg"],
                "inverted": io_block["best_fit"]["theta23_deg"],
                "difference_deg": round(abs(io_block["best_fit"]["theta23_deg"] - no_block["best_fit"]["theta23_deg"]), 4),
            },
            "abs_dm31_consistency": {
                "normal_ev2": no_block["best_fit"]["abs_dm31_ev2"],
                "inverted_ev2": io_block["best_fit"]["abs_dm31_ev2"],
                "relative_difference": round(abs(io_block["best_fit"]["abs_dm31_ev2"] - no_block["best_fit"]["abs_dm31_ev2"]) / max(no_block["best_fit"]["abs_dm31_ev2"], io_block["best_fit"]["abs_dm31_ev2"]), 4),
            },
            "errors": raw.get("errors") or [],
            "retrieved_at": raw.get("retrieved_at"),
            "limitations": list(raw.get("limitations") or []) + [
                "Intervals are read off the published two-parameter scan with one-parameter thresholds; they are not a full profile-likelihood construction.",
                "The scan covers theta23 and dm31 only; the remaining oscillation parameters are fixed by the collaboration.",
            ],
        }}

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)

from __future__ import annotations

import json


class Execution:
    name: str = 'compare_and_visualize'
    description: str = 'Compares ORCA6 and IceCube results with standard expectations and published LIV limits, and renders SVG figures.'
    category: str = 'processing'

    inputs: list[dict] = [
        {'name': 'icecube_analysis', 'type': dict},
        {'name': 'icecube_raw', 'type': dict},
        {'name': 'orca_analysis', 'type': dict},
        {'name': 'orca_raw', 'type': dict},
    ]

    outputs: list[dict] = [
        {'name': 'comparison', 'type': dict},
        {'name': 'figures', 'type': dict},
    ]

    parameters: dict = {
        'planck_energy_e19_gev': {'type': float, 'default': 1.22},
    }

    WIDTH = 640
    HEIGHT = 390
    LEFT = 82
    RIGHT = 24
    TOP = 48
    BOTTOM = 62
    NO_COLOUR = '#2563eb'
    IO_COLOUR = '#f59e0b'

    def _unwrap(self, inputs, key):
        value = inputs.get(key)
        if isinstance(value, str) and value.strip()[:1] == '{':
            try:
                value = json.loads(value)
            except Exception:
                return {}
        if isinstance(value, dict) and key in value and isinstance(value[key], dict):
            return value[key]
        return value if isinstance(value, dict) else {}

    def _head(self, title, xlabel, ylabel):
        plot_w = self.WIDTH - self.LEFT - self.RIGHT
        plot_h = self.HEIGHT - self.TOP - self.BOTTOM
        parts = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %d %d" width="%d" height="%d" font-family="Helvetica, Arial, sans-serif">' % (self.WIDTH, self.HEIGHT, self.WIDTH, self.HEIGHT)]
        parts.append('<rect width="100%" height="100%" fill="#ffffff"/>')
        parts.append('<text x="%d" y="26" font-size="15" font-weight="600" fill="#111827">%s</text>' % (self.LEFT, title))
        parts.append('<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="#9ca3af"/>' % (self.LEFT, self.TOP, plot_w, plot_h))
        parts.append('<text x="%.1f" y="%d" font-size="12" fill="#374151" text-anchor="middle">%s</text>' % (self.LEFT + plot_w / 2.0, self.HEIGHT - 16, xlabel))
        mid = self.TOP + plot_h / 2.0
        parts.append('<text x="18" y="%.1f" font-size="12" fill="#374151" text-anchor="middle" transform="rotate(-90 18 %.1f)">%s</text>' % (mid, mid, ylabel))
        return parts

    def _axes(self, parts, x_ticks, y_ticks):
        plot_w = self.WIDTH - self.LEFT - self.RIGHT
        plot_h = self.HEIGHT - self.TOP - self.BOTTOM
        for frac, label in x_ticks:
            x = self.LEFT + frac * plot_w
            parts.append('<line x1="%.1f" y1="%d" x2="%.1f" y2="%d" stroke="#e5e7eb"/>' % (x, self.TOP, x, self.TOP + plot_h))
            parts.append('<text x="%.1f" y="%d" font-size="11" fill="#4b5563" text-anchor="middle">%s</text>' % (x, self.TOP + plot_h + 16, label))
        for frac, label in y_ticks:
            y = self.TOP + plot_h - frac * plot_h
            parts.append('<line x1="%d" y1="%.1f" x2="%d" y2="%.1f" stroke="#e5e7eb"/>' % (self.LEFT, y, self.LEFT + plot_w, y))
            parts.append('<text x="%d" y="%.1f" font-size="11" fill="#4b5563" text-anchor="end">%s</text>' % (self.LEFT - 8, y + 4, label))
        return parts

    def _bar_chart(self, title, xlabel, ylabel, x_values, values, x_min, x_max, y_max, colour, x_ticks, y_ticks):
        parts = self._head(title, xlabel, ylabel)
        parts = self._axes(parts, x_ticks, y_ticks)
        plot_w = self.WIDTH - self.LEFT - self.RIGHT
        plot_h = self.HEIGHT - self.TOP - self.BOTTOM
        span = (x_max - x_min) or 1.0
        slot = plot_w / float(len(values) or 1) * 0.76
        for x_value, value in zip(x_values, values):
            height = (value / y_max) * plot_h if y_max else 0.0
            x = self.LEFT + ((x_value - x_min) / span) * plot_w - slot / 2.0
            parts.append('<rect x="%.1f" y="%.1f" width="%.1f" height="%.1f" fill="%s" fill-opacity="0.85"/>' % (x, self.TOP + plot_h - height, slot, height, colour))
        parts.append('</svg>')
        return ''.join(parts)

    def _line_chart(self, title, xlabel, ylabel, series, x_min, x_max, y_max, x_ticks, y_ticks, thresholds):
        parts = self._head(title, xlabel, ylabel)
        parts = self._axes(parts, x_ticks, y_ticks)
        plot_w = self.WIDTH - self.LEFT - self.RIGHT
        plot_h = self.HEIGHT - self.TOP - self.BOTTOM
        span = (x_max - x_min) or 1.0
        for threshold in thresholds:
            if threshold <= y_max:
                y = self.TOP + plot_h - (threshold / y_max) * plot_h
                parts.append('<line x1="%d" y1="%.1f" x2="%d" y2="%.1f" stroke="#ef4444" stroke-dasharray="4 4"/>' % (self.LEFT, y, self.LEFT + plot_w, y))
        for entry in series:
            points = entry[0]
            colour = entry[1]
            coords = []
            for x, y in points:
                px = self.LEFT + ((x - x_min) / span) * plot_w
                py = self.TOP + plot_h - (min(y, y_max) / y_max) * plot_h
                coords.append('%.1f,%.1f' % (px, py))
            if coords:
                parts.append('<polyline fill="none" stroke="%s" stroke-width="2" points="%s"/>' % (colour, ' '.join(coords)))
        parts.append('</svg>')
        return ''.join(parts)

    def run(self, inputs, parameters, context):
        ice = self._unwrap(inputs, 'icecube_analysis')
        ice_raw = self._unwrap(inputs, 'icecube_raw')
        orca = self._unwrap(inputs, 'orca_analysis')
        orca_raw = self._unwrap(inputs, 'orca_raw')
        planck = float(parameters.get('planck_energy_e19_gev', 1.22)) * 1e19

        if not ice or not orca:
            return {'comparison': {'status': 'no_input', 'message': 'Both branch analyses are required.'}, 'figures': {}}

        energy = ice.get('energy') or {}
        zenith = ice.get('zenith') or {}
        probe = ice.get('power_law_probe') or {}
        ordering = orca.get('mass_ordering') or {}
        no_block = ordering.get('normal') or {}
        io_block = ordering.get('inverted') or {}
        no_best = no_block.get('best_fit') or {}
        io_best = io_block.get('best_fit') or {}

        checks = []
        if probe:
            checks.append({
                'name': 'IceCube single power-law description',
                'measured': 'chi2/dof = %.1f over 10^%.2f-10^%.2f GeV (gamma = %.2f +- %.2f)' % (
                    probe.get('chi2_per_dof') or 0, (probe.get('fit_range_log10_gev') or [0, 0])[0],
                    (probe.get('fit_range_log10_gev') or [0, 0])[1], probe.get('gamma') or 0, probe.get('gamma_error') or 0),
                'reference': 'chi2/dof of order 1 for an adequate model',
                'sigma': None,
                'verdict': 'adequate' if probe.get('adequate_description') else 'inadequate - descriptive only',
            })
        if zenith.get('up_down_ratio') is not None:
            checks.append({
                'name': 'IceCube up/down event ratio',
                'measured': 'U/D = %.3f +- %.3f' % (zenith['up_down_ratio'], zenith.get('up_down_ratio_error') or 0),
                'reference': '1.0 (horizon-symmetry reference, not a physical prediction)',
                'sigma': None,
                'verdict': 'asymmetric as expected from effective area and Earth attenuation',
            })
        checks.append({
            'name': 'ORCA6 mass ordering preference',
            'measured': '%s preferred, delta chi2 = %.3f' % (ordering.get('preferred_ordering'), abs(ordering.get('delta_chi2_no_minus_io') or 0)),
            'reference': 'delta chi2 = 0 (no sensitivity)',
            'sigma': ordering.get('significance_sigma_1dof'),
            'verdict': 'no significant preference' if (ordering.get('significance_sigma_1dof') or 0) < 3 else 'preference reported',
        })
        interval = no_block.get('theta23_1sigma') or []
        if len(interval) == 2:
            inside = interval[0] <= 45.0 <= interval[1]
            checks.append({
                'name': 'ORCA6 theta23 vs maximal mixing',
                'measured': '%.3f deg (1 sigma %.3f-%.3f)' % (no_best.get('theta23_deg', 0), interval[0], interval[1]),
                'reference': '45 deg (maximal mixing)',
                'sigma': None,
                'verdict': 'maximal mixing allowed' if inside else 'maximal mixing outside 1 sigma',
            })

        max_energy = float(energy.get('max_energy_gev') or 0)
        literature = [
            {'source': 'KM3NeT/ORCA6 atmospheric LIV search (arXiv:2603.04264)', 'quantity': '95% CL limits on isotropic flavour-off-diagonal SME coefficients (units 1e-23 GeV)', 'value': 'a_mu_tau < 0.48, a_e_mu < 2.53, a_e_tau < 4.70', 'url': 'https://arxiv.org/abs/2603.04264'},
            {'source': 'KM3-230213A ultra-high-energy event (arXiv:2502.18256)', 'quantity': 'second-order LIV scale at 90% CL', 'value': 'Lambda_2 > 5.0e19 GeV for E_nu ~ 220 PeV', 'url': 'https://arxiv.org/abs/2502.18256'},
            {'source': 'Stecker & Scully (arXiv:1404.7025)', 'quantity': 'superluminal velocity parameters from IceCube PeV neutrinos', 'value': 'delta_nu_e <= 5.2e-21; delta_nu <= 1.0e-20', 'url': 'https://arxiv.org/abs/1404.7025'},
            {'source': 'Borriello et al. (arXiv:1303.5843)', 'quantity': 'LIV parameter from two IceCube PeV events', 'value': 'delta < O(1e-18); M_QG >~ 1e-4 M_Pl linear, ~1e5 M_Pl quadratic', 'url': 'https://arxiv.org/abs/1303.5843'},
        ]

        scale = {
            'highest_energy_in_sample_gev': max_energy,
            'km3_230213a_energy_gev': 2.2e8,
            'ratio_sample_to_km3_230213a': round(max_energy / 2.2e8, 4) if max_energy else None,
            'planck_energy_gev': planck,
            'note': 'The IceCube sample analysed here is a track sample whose energies lie orders of magnitude below the single 220 PeV event used in the KM3NeT second-order LIV bound.',
        }

        comparison = {
            'status': 'ok',
            'orca6': {
                'best_fit_normal': no_best,
                'best_fit_inverted': io_best,
                'ordering_delta_chi2': ordering.get('delta_chi2_no_minus_io'),
                'ordering_significance_sigma': ordering.get('significance_sigma_1dof'),
                'preferred_ordering': ordering.get('preferred_ordering'),
                'theta23_1sigma': no_block.get('theta23_1sigma'),
                'theta23_90pct': no_block.get('theta23_90pct'),
                'dm31_1sigma': no_block.get('dm31_1sigma'),
                'dm31_90pct': no_block.get('dm31_90pct'),
                'dataset_doi': (orca.get('dataset') or {}).get('doi'),
                'checksums_all_match': orca.get('checksums_all_match'),
                'analysis_window': (orca.get('binning') or {}).get('summary'),
            },
            'icecube': {
                'sample_size': ice.get('sample_size'),
                'seasons': ice.get('seasons'),
                'spectral_index': probe.get('gamma'),
                'spectral_index_error': probe.get('gamma_error'),
                'chi2_per_dof': probe.get('chi2_per_dof'),
                'power_law_adequate': probe.get('adequate_description'),
                'up_down_ratio': zenith.get('up_down_ratio'),
                'up_down_error': zenith.get('up_down_ratio_error'),
                'upgoing_fraction': zenith.get('upgoing_fraction'),
                'max_energy_gev': max_energy,
                'events_above_1pev': energy.get('events_above_1pev'),
                'events_above_10pev': energy.get('events_above_10pev'),
                'counts_per_decade': energy.get('counts_per_decade'),
                'dataset_doi': (ice.get('dataset') or {}).get('doi'),
            },
            'consistency_checks': checks,
            'literature_constraints': literature,
            'energy_scale_comparison': scale,
            'interpretation': 'Independent analysis of two public datasets. The ORCA6 branch re-extracts the published oscillation scan and confirms a best fit with no strong mass-ordering preference. The IceCube branch characterises the released track sample: its reconstructed-energy distribution is not described by a single power law, so no spectral index or LIV limit is claimed from it. Neither branch derives a new LIV coefficient, and no joint likelihood is formed.',
            'limitations': list(ice.get('limitations') or []) + list(orca.get('limitations') or []) + [
                'The comparison with published LIV limits is a literature cross-reference, not an independent limit calculation.',
                'No shared likelihood or joint fit between ORCA6 and IceCube is performed.',
            ],
            'retrieved_at': orca.get('retrieved_at'),
        }

        figures = self._figures(ice_raw, no_block, io_block)
        return {'comparison': comparison, 'figures': figures}

    def _figures(self, ice_raw, no_block, io_block):
        sample = ice_raw.get('sample') or {}
        counts = sample.get('energy_counts') or []
        centers = sample.get('energy_bin_centers_log10_gev') or []
        zcounts = sample.get('zenith_counts') or []
        zcenters = sample.get('zenith_bin_centers_deg') or []
        outputs = {}

        if counts and centers:
            top = max(counts) or 1
            x0, x1 = min(centers), max(centers)
            x_ticks = [((k - x0) / (x1 - x0), '10^%d' % k) for k in range(1, 8) if x0 <= k <= x1]
            y_ticks = [(f, '%d' % round(f * top)) for f in (0.0, 0.25, 0.5, 0.75, 1.0)]
            outputs['energy_spectrum'] = {
                'svg': self._bar_chart('IceCube track events: reconstructed energy', 'reconstructed energy E [GeV]', 'events per 0.25 dex', centers, counts, x0, x1, top * 1.05, self.NO_COLOUR, x_ticks, y_ticks),
                'caption': 'Raw event counts per 0.25 dex in reconstructed energy for the %d-event sample. No detector response is unfolded.' % int(sample.get('events') or 0),
            }

        if zcounts and zcenters:
            top = max(zcounts) or 1
            x_ticks = [(t / 180.0, str(t)) for t in (0, 45, 90, 135, 180)]
            y_ticks = [(f, '%d' % round(f * top)) for f in (0.0, 0.5, 1.0)]
            outputs['zenith_distribution'] = {
                'svg': self._bar_chart('IceCube track events: zenith angle', 'reconstructed zenith [deg]', 'events per 10 deg', zcenters, zcounts, 0.0, 180.0, top * 1.05, '#0ea5e9', x_ticks, y_ticks),
                'caption': 'Zenith distribution of the same sample; 90 deg marks the horizon, above which events are up-going (Earth-crossing).',
            }

        theta_series = []
        for block, colour in ((no_block, self.NO_COLOUR), (io_block, self.IO_COLOUR)):
            points = [(row['theta23_deg'], row['delta_chi2']) for row in (block.get('theta23_profile') or [])]
            if points:
                theta_series.append((points, colour))
        if theta_series:
            xs = [point[0] for entry in theta_series for point in entry[0]]
            ys = [point[1] for entry in theta_series for point in entry[0]]
            x_min, x_max = min(xs), max(xs)
            y_max = min(20.0, max(5.0, max(ys) * 1.1))
            x_ticks = [((t - x_min) / (x_max - x_min), str(t)) for t in (35, 40, 45, 50, 55) if x_min <= t <= x_max]
            outputs['orca_theta23'] = {
                'svg': self._line_chart('ORCA6 scan: theta23 profile', 'theta23 [deg]', 'delta chi2', theta_series, x_min, x_max, y_max, x_ticks, [(0.0, '0'), (0.5, '%.1f' % (y_max / 2)), (1.0, '%.0f' % y_max)], [1.0, 2.71]),
                'caption': 'Profiled delta chi-square versus theta23 for normal (blue) and inverted (orange) ordering. Dashed lines mark delta chi2 = 1 and 2.71.',
            }

        dm_series = []
        for block, colour in ((no_block, self.NO_COLOUR), (io_block, self.IO_COLOUR)):
            points = []
            for row in (block.get('dm31_profile') or []):
                points.append((abs(row['dm31_ev2']) * 1e3, row['delta_chi2']))
            points.sort()
            if points:
                dm_series.append((points, colour))
        if dm_series:
            xs = [point[0] for entry in dm_series for point in entry[0]]
            ys = [point[1] for entry in dm_series for point in entry[0]]
            x_min, x_max = min(xs), max(xs)
            y_max = min(20.0, max(5.0, max(ys) * 1.1))
            x_ticks = [((t - x_min) / (x_max - x_min), '%.1f' % t) for t in (1.0, 2.0, 3.0, 4.0) if x_min <= t <= x_max]
            outputs['orca_dm31'] = {
                'svg': self._line_chart('ORCA6 scan: |dm31| profile', '|dm31| [1e-3 eV^2]', 'delta chi2', dm_series, x_min, x_max, y_max, x_ticks, [(0.0, '0'), (0.5, '%.1f' % (y_max / 2)), (1.0, '%.0f' % y_max)], [1.0, 2.71]),
                'caption': 'Profiled delta chi-square versus |dm31| for both orderings, read off the published scan grid.',
            }

        return outputs

    def build_output(self, inputs, parameters, context):
        return self.run(inputs, parameters, context)
